package scanner

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"
)

const (
	infoLabelEnglish = "ROM files extensions accepted:"
	infoLabelFrench  = "Extensions des fichiers ROMs permises:"
	infoMaxLineBytes = 1 << 20
)

// errNoExtensions means the file was readable but contained no usable
// extension section. It is not a malformed-file error.
var errNoExtensions = errors.New("no supported ROM extensions found")

// parseInfo parses the extension sections generated by Batocera. It supports:
//
//   - Batocera 43.1: ROM files extensions accepted: ".nes .zip"
//   - Batocera 43.1 with its comment concatenated after the closing quote
//   - master inline: ROM files extensions accepted: .nes .zip
//   - master emulator/core blocks: one "- emulator/core: .ext ..." line per
//     core, merged into one deduplicated set
//
// English is preferred. The French section is used only when the English
// section yields no usable extensions. All other text is ignored.
func parseInfo(reader io.Reader) ([]string, error) {
	if reader == nil {
		return nil, fmt.Errorf("info reader is required")
	}

	lines, err := readInfoLines(reader)
	if err != nil {
		return nil, err
	}

	extensions := parseInfoSection(lines, infoLabelEnglish)
	if len(extensions) == 0 {
		extensions = parseInfoSection(lines, infoLabelFrench)
	}
	if len(extensions) == 0 {
		return nil, errNoExtensions
	}
	return extensions, nil
}

func readInfoLines(reader io.Reader) ([]string, error) {
	lineScanner := bufio.NewScanner(reader)
	lineScanner.Buffer(make([]byte, 0, 64*1024), infoMaxLineBytes)

	var lines []string
	for lineScanner.Scan() {
		line := lineScanner.Text()
		if len(lines) == 0 {
			line = strings.TrimPrefix(line, "\uFEFF")
		}
		lines = append(lines, line)
	}
	if err := lineScanner.Err(); err != nil {
		return nil, fmt.Errorf("read info lines: %w", err)
	}
	return lines, nil
}

func parseInfoSection(lines []string, label string) []string {
	for index, line := range lines {
		remainder, ok := stripInfoLabel(line, label)
		if !ok {
			continue
		}
		return parseInfoAfterLabel(lines[index+1:], remainder)
	}
	return nil
}

func stripInfoLabel(line, label string) (string, bool) {
	trimmed := strings.TrimSpace(line)
	if len(trimmed) < len(label) {
		return "", false
	}
	if !strings.EqualFold(trimmed[:len(label)], label) {
		return "", false
	}
	return strings.TrimSpace(trimmed[len(label):]), true
}

func parseInfoAfterLabel(following []string, remainder string) []string {
	if strings.HasPrefix(remainder, `"`) {
		end := strings.IndexByte(remainder[1:], '"')
		if end < 0 {
			return nil
		}
		return parseExtensionList(remainder[1 : 1+end])
	}
	if remainder != "" {
		return parseExtensionList(remainder)
	}
	return parseInfoBullets(following)
}

func parseInfoBullets(following []string) []string {
	var extensions []string
	for _, rawLine := range following {
		line := strings.TrimSpace(rawLine)
		if !strings.HasPrefix(line, "- ") {
			// Official master output places the comment after the core block.
			// Once the contiguous block ends, no later line is treated as an
			// extension line.
			break
		}

		body := strings.TrimSpace(strings.TrimPrefix(line, "- "))
		name, values, ok := strings.Cut(body, ":")
		if !ok || strings.TrimSpace(name) == "" || strings.TrimSpace(values) == "" {
			break
		}
		if len(strings.Fields(name)) != 1 {
			// Official names are tokens such as "fceumm" or "libretro/fceumm".
			// A prose line that happens to start with "- " and contains a colon
			// must not become an extension source.
			break
		}
		extensions = append(extensions, parseExtensionList(values)...)
	}
	return uniqueSortedExtensions(extensions)
}

func parseExtensionList(value string) []string {
	value = strings.TrimSpace(value)
	if len(value) >= 2 && value[0] == '"' && value[len(value)-1] == '"' {
		value = value[1 : len(value)-1]
	}

	extensions := make([]string, 0)
	for _, token := range strings.Fields(value) {
		if extension, ok := normalizeExtension(token); ok {
			extensions = append(extensions, extension)
		}
	}
	return uniqueSortedExtensions(extensions)
}

func normalizeExtension(token string) (string, bool) {
	token = strings.TrimSpace(token)
	if len(token) < 2 || token[0] != '.' {
		return "", false
	}
	extension := strings.ToLower(token)
	for _, char := range extension[1:] {
		if (char >= 'a' && char <= 'z') || (char >= '0' && char <= '9') ||
			char == '-' || char == '_' || char == '+' {
			continue
		}
		return "", false
	}
	return extension, true
}

func uniqueSortedExtensions(extensions []string) []string {
	seen := make(map[string]struct{}, len(extensions))
	result := make([]string, 0, len(extensions))
	for _, extension := range extensions {
		if _, exists := seen[extension]; exists {
			continue
		}
		seen[extension] = struct{}{}
		result = append(result, extension)
	}
	sort.Strings(result)
	return result
}
